/**
 * @jest-environment node
 *
 * The real pdf-lib needs to read the generated bytes back, which fails under
 * jsdom's foreign-realm Uint8Array, so this suite runs in the node environment.
 */
import { PDFArray, PDFDocument, PDFDict, PDFName, PDFRawStream, PDFStream } from 'pdf-lib';
import { inflateSync } from 'node:zlib';
import { readPdfContent } from '@/lib/fonts/pdf-test-reader';
import {
  buildExportFileName,
  formatPrice,
  generateProductsPdf,
  ROWS_PER_PAGE,
  type PdfMeta,
  type ProductRow,
} from './pdf';

const makeRows = (n: number): ProductRow[] =>
  Array.from({ length: n }, (_, i) => ({
    code: `P${String(i).padStart(3, '0')}`,
    name: `Producto ${i}`,
    stock: i,
    price: 1000 + i,
  }));

const META: PdfMeta = {
  branchName: 'Sucursal Depósito',
  branchCode: 'DEP',
  date: new Date(2026, 7, 6, 15, 30),
};

const loadPdf = (base64: string) => PDFDocument.load(Buffer.from(base64, 'base64'));

// Con Poppins embebida los `Tj` son ids de glifo: el lector compartido los
// traduce con el CMap /ToUnicode, así que las aserciones de texto no cambian.
const pdfText = async (base64: string): Promise<string> => {
  const content = await readPdfContent(Buffer.from(base64, 'base64'));
  return content.text.join('\n');
};

const imageXObjects = (pdfDoc: PDFDocument, pageIndex = 0): PDFRawStream[] => {
  const resources = pdfDoc.getPages()[pageIndex].node.Resources();
  const xobjects = resources?.lookup(PDFName.of('XObject'), PDFDict);
  if (!xobjects) return [];
  return [...xobjects.entries()]
    .map(([, ref]) => pdfDoc.context.lookup(ref))
    .filter(
      (value): value is PDFRawStream =>
        value instanceof PDFRawStream &&
        String(value.dict.get(PDFName.of('Subtype'))) === '/Image'
    );
};

describe('generateProductsPdf', () => {
  test('renders a valid single-page PDF for a small selection', async () => {
    const base64 = await generateProductsPdf(makeRows(5), META);

    const pdfDoc = await loadPdf(base64);
    expect(pdfDoc.getPageCount()).toBe(1);
  });

  test('overflows to a new page without truncation and stays valid', async () => {
    const base64 = await generateProductsPdf(makeRows(80), META);

    const pdfDoc = await loadPdf(base64);
    expect(pdfDoc.getPageCount()).toBe(3);
  });

  test('spills to a second page right past the recomputed row capacity', async () => {
    const base64 = await generateProductsPdf(makeRows(33), META);

    const pdfDoc = await loadPdf(base64);
    expect(pdfDoc.getPageCount()).toBe(2);
  });

  test('an empty selection still produces a valid one-page PDF', async () => {
    const base64 = await generateProductsPdf([], META);

    const pdfDoc = await loadPdf(base64);
    expect(pdfDoc.getPageCount()).toBe(1);
  });

  test('dibuja el logo de la marca con vectores, sin PNG embebido', async () => {
    const pdfDoc = await loadPdf(await generateProductsPdf(makeRows(3), META));

    // La frutilla ahora se dibuja con las primitivas de pdf-lib: no hay imagen.
    expect(imageXObjects(pdfDoc)).toHaveLength(0);
  });

  test('la frutilla cae dentro de su caja del encabezado', async () => {
    const pdfDoc = await loadPdf(await generateProductsPdf(makeRows(3), META));
    const contents = pdfDoc.getPage(0).node.Contents();
    const refs = contents instanceof PDFArray ? contents.asArray() : [contents!];
    const raw = refs
      .map((ref) => inflateSync(pdfDoc.context.lookup(ref, PDFStream).getContents()).toString('latin1'))
      .join('\n');

    // El logo se dibuja en un sistema local: traslado a la esquina superior
    // izquierda de su caja y escala 100 → 40 pt con el eje Y invertido.
    expect(raw).toContain(`1 0 0 1 36 ${841.89 - 36} cm`);
    expect(raw).toContain('0.4 0 0 -0.4 0 0 cm');

    // Las curvas del SVG salen en coordenadas locales (`0..100`); los lunares
    // son 3 círculos de 4 curvas cada uno y van en coordenadas de página.
    const curves = [...raw.matchAll(/((?:-?[\d.]+ ){5}-?[\d.]+) c(?=\s)/g)].map((match) =>
      match[1].split(' ').map(Number)
    );
    const dots = curves.slice(-12);
    expect(dots).toHaveLength(12);
    const [left, bottom] = [36, 841.89 - 36 - 40];
    for (const values of dots) {
      for (const x of [values[0], values[2], values[4]]) {
        expect(x).toBeGreaterThanOrEqual(left);
        expect(x).toBeLessThanOrEqual(left + 40);
      }
      for (const y of [values[1], values[3], values[5]]) {
        expect(y).toBeGreaterThanOrEqual(bottom);
        expect(y).toBeLessThanOrEqual(bottom + 40);
      }
    }
  });

  test('prints the branch name and the export date in the header', async () => {
    const text = await pdfText(await generateProductsPdf(makeRows(3), META));

    expect(text).toContain('Sucursal Depósito');
    expect(text).toContain('DEP');
    expect(text).toContain('06/08/2026');
  });

  test('prints the selected product count and their total units', async () => {
    const text = await pdfText(await generateProductsPdf(makeRows(33), META));

    // makeRows() gives stock 0..32, so the 33 rows add up to 528 units.
    expect(text).toContain('33 productos');
    expect(text).toContain('528 unidades');
  });

  test('numbers every page of a multi-page export', async () => {
    const text = await pdfText(await generateProductsPdf(makeRows(80), META));

    expect(text).toContain('Página 1 de 3');
    expect(text).toContain('Página 3 de 3');
  });

  test('pinta el título con el frutilla de la marca y el encabezado de tabla en blanco', async () => {
    const { colors } = await readPdfContent(
      Buffer.from(await generateProductsPdf(makeRows(3), META), 'base64')
    );

    // #C8323C = rgb(0,78 · 0,20 · 0,24): el frutilla de la marca; el encabezado va en blanco encima.
    expect(colors.get('Sucursal Depósito (DEP)')).toEqual([0.78, 0.2, 0.24]);
    expect(colors.get('Código')).toEqual([1, 1, 1]);
    // El contenido va en cacao #4A2C2A.
    expect(colors.get('P000')).toEqual([0.29, 0.17, 0.16]);
  });

  test('embebe Poppins Regular y SemiBold en lugar de Helvetica', async () => {
    const { fonts } = await readPdfContent(
      Buffer.from(await generateProductsPdf(makeRows(3), META), 'base64')
    );

    expect(fonts.join(' ')).toContain('Poppins-Regular');
    expect(fonts.join(' ')).toContain('Poppins-SemiBold');
    expect(fonts.join(' ')).not.toContain('Helvetica');
  });
});

describe('ROWS_PER_PAGE', () => {
  test('accounts for the taller title block plus the reserved summary line', () => {
    // 841.89 - 36 - 40 logo - 26 título - 16 metadatos - 16 hueco = 707.89
    // menos 22 de encabezado de tabla y 70 reservados al pie: floor(615.89 / 20) = 30.
    expect(ROWS_PER_PAGE).toBe(30);
  });
});

describe('buildExportFileName', () => {
  test('formats inventario-DEP-20260806.pdf for branch DEP on 2026-08-06', () => {
    expect(buildExportFileName('DEP', new Date(2026, 7, 6))).toBe(
      'inventario-DEP-20260806.pdf'
    );
  });
});

describe('formatPrice', () => {
  test('formats ARS in the house style', () => {
    expect(formatPrice(1250)).toBe('$1.250,00');
  });
});
